/** Milliseconds since the Unix epoch (rumu-core's `Timestamp` alias). */
export type Timestamp = number

/** The tag of the recorded turn-failure marker. The marker carries no text;
 * the timeline skips it and the error row (`owedReply`) reads it while the
 * reply is still owed. */
export const TURN_ERROR_TAG = 'turn.error'

/** A plugin-authored tail append: a note's content (an empty-text note is a
 * marker). The kernel fills the node's `source` with the plugin's name. */
export type Effect = Content

/** The tag/version the catalog payload uses. */
export const CATALOG_TAG = 'memory.catalog'
/** The once-per-path assistant introduction: model context only, never shown. */
export const ASSISTANT_INTRO_TAG = 'assistant.intro'
export const CATALOG_VERSION = 3

export const TASK_TAG = 'kernel.task'
export const TASK_VERSION = 1

/**
 * The built-in workspace holding rumu's own data (`@rumu:/cards`,
 * `@rumu:/sessions`). Mirrors `RUMU_WORKSPACE` in rumu-core; the leading `@`
 * means no user preset can collide with it.
 */
export const INTERNAL_WORKSPACE = '@rumu'

/**
 * A session's scratch directory (`RUMU_HOME/scratch/<session id>`), default
 * when the session has no project workspace. Mirrors `SCRATCH_WORKSPACE` in
 * rumu-core; per-session, so never registered or mounted.
 */
export const SCRATCH_WORKSPACE = '@scratch'

// ---- WebSocket protocol ----

export interface WsRequest {
  jsonrpc: '2.0'
  id: number
  method: string
  params: Record<string, unknown>
}

export type WsMessage =
  | { jsonrpc: '2.0'; id: number; result: unknown }
  | { jsonrpc: '2.0'; id: number; error: { code: number; message: string } }
  | { jsonrpc: '2.0'; method: string; params: Record<string, unknown> }

export interface SessionTreeResult {
  session: SessionInfo
  nodes: Node[]
  branches: Branch[]
  /** Branches with a running turn, and what their model call streamed. */
  live: Record<BranchId, LiveTurn>
}

export interface BranchPathResult {
  state: PathState
}

// ---- Push payloads ----

export interface NodeAppendedPush {
  branch: BranchId
  node: Node
}

export interface LlmDeltaPush {
  branch: BranchId
  text?: string
  reasoning?: string
  /** The delta's number within its model call (1-based). */
  seq: number
}

/** What a running branch's model call has streamed so far. */
export interface LiveTurn {
  text: string
  reasoning: string
  /** The number of the last delta folded in. */
  seq: number
}

export interface BranchUpdatedPush {
  branch: Branch
}

/** A question a tool call put to the user (`decision.requested` push and
 * `decision.list` rows); answered with `decision.answer`. */
export interface PendingDecision {
  id: string
  session: SessionId
  branch: BranchId
  call_id: string
  request: DecisionRequest
  /** When it is withdrawn unanswered (ms since the epoch), unless held. */
  expires_at?: number
}

/** What a tool call asks the user to approve. Names are for display; the
 * `_id` fields are the deck ids. */
export type DecisionRequest =
  | AskRequest
  | QuestionsRequest
  | MountRequest
  | WriteRequest
  | LinkRequest
  | ProjectCreateRequest
  | WorkspaceChangeRequest

/** How long an approval lasts. */
export type DecisionScope = 'once' | 'session' | 'always'

/** The answer to a `decision.requested`: an approval, or the answers to a
 * `questions` request (none when the user dismissed them). */
export type DecisionAnswer = { allow: boolean; scope?: DecisionScope } | { answers?: QuestionAnswer[] }

/** The answer to one question: the labels chosen and/or the user's own words. */
export interface QuestionAnswer {
  selected: string[]
  custom?: string
}

/** `agent` naming another assistant: `from` hands `to` the task. */
export interface AskRequest {
  kind: 'ask'
  from: string
  from_id: string
  to: string
  to_id: string
  task: string
}

/** `ask`: questions from `from` for the user. */
export interface QuestionsRequest {
  kind: 'questions'
  from: string
  from_id: string
  questions: Question[]
}

/** One question to the user; any can also be answered in their own words. */
export interface Question {
  question: string
  /** A word or two naming it (the tab of a multi-question request). */
  header?: string
  options: QuestionOption[]
  /** Whether several options may be chosen. */
  multiple: boolean
}

export interface QuestionOption {
  label: string
  description?: string
}

/** `card_mount` without a grant: `from` mounts `deck` at `at`. */
export interface MountRequest {
  kind: 'card_mount'
  from: string
  from_id: string
  deck: string
  deck_id: string
  at: string
}

/** A card write into a deck that is not `from`'s own: `content` at `path`,
 * moved from `move_from` when set. */
export interface WriteRequest {
  kind: 'card_write'
  from: string
  from_id: string
  deck: string
  deck_id: string
  path: string
  move_from?: string | null
  content: string
}

/** A link into another deck: the card at `path` would share `target`. */
export interface LinkRequest {
  kind: 'card_link'
  from: string
  from_id: string
  to: string
  to_id: string
  target: string
  path: string
}

/** `card_mount(create, at: "project")`: `from` wants a project named `name`. */
export interface ProjectCreateRequest {
  kind: 'project_create'
  from: string
  from_id: string
  name: string
}

/** A registered workspace entry would change: `before`/`after` are its YAML. */
export interface WorkspaceChangeRequest {
  kind: 'workspace_change'
  from: string
  from_id: string
  name: string
  before: string
  after: string
}

/** `decision.resolved` push: answered, or the turn was aborted. */
export interface DecisionResolvedPush {
  id: string
}

export interface SessionUpdatedPush {
  session: SessionInfo
}

/** `session.deleted` push: the session and its whole tree are gone. */
export interface SessionDeletedPush {
  session: SessionInfo
}

export interface HookFiredPush {
  branch: BranchId
  event: string
  plugin: string
  hook_id: string
  effects: Effect[]
  decision: Decision
  /** Set when the event came from an internal `code` call. */
  parent_call?: string
}

/** `tool.progress` push: a running tool's incremental update. */
export interface ToolProgressPush {
  branch: BranchId
  call_id: string
  /** Append-only text chunk. */
  append?: string
  /** Whole structured payload (latest wins). */
  data?: Tagged
}

/** `task.started` / `task.done` push: a task snapshot. */
export interface TaskInfoPush {
  task: TaskInfo
}

/** `task.progress` push: a running task's incremental output. */
export interface TaskProgressPush {
  id: TaskId
  branch: BranchId
  /** Append-only text chunk. */
  append?: string
  /** Latest structured payload (whole value, latest wins). */
  data?: Tagged
  /** Sent once when a background agent's child branch is created. */
  kind?: TaskKind
}

export interface TurnPush {
  branch: BranchId
  /** Why the turn started. */
  reason?: 'prompt' | 'regenerate' | 'retry' | 'wake'
  /** Posting plugins, for wake turns. */
  sources?: string[]
}

/** `turn.retrying` push: the model call failed transiently and will be
 * replayed after a backoff wait. */
export interface TurnRetryingPush {
  branch: BranchId
  /** Which retry is coming up, 1-based. */
  attempt: number
  max: number
  retry_in_ms: number
  message: string
}

/** A user prompt accepted while the branch was busy; it lands on the path at
 * the next safe point and arrives as a normal `node.appended` user node. */
export interface PromptQueuedPush {
  branch: BranchId
  text: string
}

/** A steering prompt refused by a hook while the turn kept running: the turn
 * is untouched, so this is a toast only. */
export interface PromptBlockedPush {
  branch: BranchId
  message: string
}

export interface TurnErrorPush {
  branch: BranchId
  message: string
  /** The failure was recorded as a `turn.error` marker on the branch, which
   * the error row (`owedReply`) reads; an unrecorded one is a toast. */
  recorded?: boolean
  /** True when a prompt hook refused the turn before it started: nothing was
   * recorded and no reply is owed, so the refusal is a toast, not a failure
   * row. */
  blocked?: boolean
}

/** Non-fatal server warning (e.g. a failed post delivery). */
export interface WarningPush {
  message: string
}

export type ToastKind = 'error' | 'info'
